#include <pthread.h>
#include <stdio.h>

void *printHello(void *arg) {
    printf("Hello from thread!\n");
    return NULL;
}

int main() {
    pthread_t thread1;
    pthread_create(&thread1, NULL, printHello, NULL);
    pthread_join(thread1, NULL);
    printf("Thread has finished.\n");
    return 0;
}
